    @Autowired JdbcTemplate jdbc;@Autowired MockMvc mvc;@Autowired EnquiryService enquiries;@Autowired EnquiryMaintenance maintenance;@Autowired IdentityService identity;@Autowired StoreService stores;@Autowired CatalogService catalog;@Autowired MediaService media;
    @Autowired org.springframework.transaction.PlatformTransactionManager transactionManager;
    UUID global,admin,a,b,customer,other,store,otherStore,product,otherProduct,category;final Gson json=new Gson();
    @BeforeEach void setup()throws Exception{
        SecurityContextHolder.clearContext();jdbc.execute("TRUNCATE vw_account,vw_store,vw_category,vw_brand,vw_product,vw_media_upload,vw_enquiry,vw_enquiry_event,vw_audit_event,vw_rate_limit,SPRING_SESSION CASCADE");
        global=account("WORKFORCE","global-enquiry@example.test","Global operator",true);admin=account("WORKFORCE","owner-enquiry@example.test","Store owner",false);a=account("WORKFORCE","staff-a-enquiry@example.test","Staff A",false);b=account("WORKFORCE","staff-b-enquiry@example.test","Staff B",false);customer=account("CUSTOMER","+919111111111","Callback Person",false);other=account("CUSTOMER","+919222222222","Other customer",false);
        store=UUID.randomUUID();otherStore=UUID.randomUUID();jdbc.update("INSERT INTO vw_store(id,name,status) VALUES(?,'Callback store','ACTIVE'),(?,'Other store','ACTIVE')",store,otherStore);member(store,admin,"STORE_ADMIN","ACTIVE");member(store,a,"STAFF","ACTIVE");member(store,b,"STAFF","ACTIVE");member(otherStore,global,"STORE_ADMIN","ACTIVE");as(global);category=(UUID)catalog.category(null,Map.of("name","Callback sarees")).get("id");product=product(store,"SALES-1");otherProduct=product(otherStore,"OTHER-1");as(customer);
    }
